public class DecisionResult {
    private String recommendation;
    private String ruleId;           // 规则ID
    private String knowledgeSource;  // 知识来源
    private Double confidence;       // 置信度
    private List<String> evidence;   // 依据
}

public DecisionResult queryKnowledge(PatientInfo patient, String knowledgeVersion) {
    KnowledgeBase kb = knowledgeRepository.getVersion(knowledgeVersion);
    DecisionResult result = kb.evaluate(patient);
    result.setKnowledgeVersion(knowledgeVersion);
    result.setQueryTime(LocalDateTime.now());
    return result;
}

public PrescriptionResult prescribe(PrescriptionRequest request) {
    // 1. 检查药物相互作用
    List<DrugInteraction> interactions = drugInteractionChecker.check(
        request.getDrugs(),
        request.getPatientInfo().getAllergies()
    );

    if (!interactions.isEmpty()) {
        return PrescriptionResult.rejected(interactions);
    }

    // 2. 开具处方
    return prescriptionService.create(request);
}

public enum AlertLevel {
    INFO,       // 提示信息，可忽略
    WARNING,    // 警告，建议处理
    CRITICAL,   // 高危，必须确认
    BLOCK       // 阻断，禁止操作
}

public void handleAlert(CDSSAlert alert) {
    if (alert.getLevel() == AlertLevel.CRITICAL || 
        alert.getLevel() == AlertLevel.BLOCK) {
        requireDoctorConfirmation(alert);
    }
}
